-- ===== 静态文章迁移到数据库 =====
-- 将原有的 6 篇静态文章内容 seed 到数据库，归属到 admin 账号
-- 运行方式: npx wrangler d1 execute yhg-db --file=db_seed_articles.sql
-- 前置条件:
--   1. 已执行 db_schema.sql 建表
--   2. 已完成 admin 初始化（/api/admin/init）
--      如果 admin 不存在，本脚本会静默跳过（不会报错）

-- ============================================================
-- 1. 同桌的你 (2026-07-02)
-- ============================================================
INSERT INTO articles (user_id, title, summary, content, slug, created_at)
SELECT id, '同桌的你', '我是绰蔚，那是我的同桌临渊。',
'<p>　　我的同桌是临渊。<br>　　是稳居年级第一的学霸，是冷得像终年不化的雪山，连眼神很少的人。<br>　　我至今记得第一次坐在他身边的场景。初秋的阳光透过教室的玻璃窗，斜斜切过他的侧脸。他垂着眼翻着崭新的课本，睫毛很长，投下浅浅的阴影，鼻梁高挺，唇线清冽。全程没有抬头，没有看我一眼，周身是生人勿近的冷淡气场。<br>　　我想，这位这个素不相识、冷漠疏离的新同桌，好像很讨厌我<br>　　后面发现不是的，临渊只是真的淡漠。<br>　　他不爱说话，班里大半同学和他同窗两年，都没和他说过几句话。偶尔有人找他问问题，他只会极简地指出关键点，声音清冷，语速极快，答完便立刻收回目光，不留半分多余温度。<br>　　圈子干净得近乎单调，没有成群结伴的玩伴，没有繁杂喧闹的应酬，不掺和八卦纷争，也从不和人拉扯嬉闹，永远独来独往。成绩遥遥领先，貌似品行端正，是老师眼里最完美的学生，所有人都觉得他干净通透，平和淡然，这样的人，像本该安稳顺遂，身边配一个温柔妥帖的人陪着，抚平他骨子里的清冷。<br>　　后面我撞见过他不为人知的另一面。<br>　　那次放学我折返教室拿遗落的笔记本，拐进教学楼后方僻静的梧桐巷，远远就看见靠墙立着一道熟悉的身影。<br>　　夕阳把他的影子拉得颀长，指尖夹着一支烟，淡白色烟雾缓缓漫开，模糊了他清隽的眉眼。他垂着眼，下颌线绷得锋利，安静吞吐，周身褪去了在校时规矩乖巧的模样，多了层压不住的沉郁。<br>　　我猛地顿住脚步，整个人愣在原地，一时间不敢上前。<br>　　从前总觉得他纯粹干净，像不染尘埃的冰雪，抽烟这件事和他格格不入，可短短几秒过后，我又慢慢了然。想来他看似平静无波的内里，也藏着无处宣泄的压抑，只是从不对外展露半分。<br>　　心头没有反感，只漫开一层淡淡的、揪着疼的酸涩。可我没有立场上前劝说，只能悄悄退后，假装从未撞见这份独属于他的隐秘。<br>　　没有朋友，没有绯闻，永远独来独往，成绩遥遥领先，是老师眼里最完美的学生，是所有人都不敢轻易靠近的冰山学霸。也是我的，唯一的同桌。<br>　　并没有太纠结，是的，我喜欢他。而恰好，我在他身边。<br>　　这份得天独厚的幸运，是我藏了两年的独家秘密，也是我无人知晓的煎熬。<br>　　这份近距离有多煎熬。我每天坐在他身边，能清晰地闻到他身上干净的洗衣液味道，能看清他指尖握笔的弧度，能看见他做题时微微蹙起的眉头，能捕捉到他偶尔抬手拂过额前碎发的小动作。偶尔凑近，还能隐约嗅到一丝浅淡的烟草气息，混着薰衣草香，成了只属于他的特殊味道。<br>　　临渊不是永远端坐听课、从不懈怠的好学生，他骨子里漠视校规。<br>　　数学课，全班都埋着头奋笔疾书、紧跟老师节奏，安静而庄严的时刻，他多半会睡着<br>　　夏日的阳光穿过窗外层层叠叠的香樟叶缝，碎金似的斜斜落进来，温柔勾勒出他清晰利落的后脑轮廓。柔软的光影铺在他摊开的空白试卷上，连纸张的纹路都被晒得温热。他睡得很安稳，脊背舒展，长睫垂落，褪去了平日里的清冷疏离，多了几分难得的温顺。<br>　　讲台上的老师余光扫过，从来视而不见。谁都舍不得叫醒这个次次稳拿第一的天才。<br>　　只有我，坐在他身侧，将这一幕尽收眼底。<br>　　每到这种午后，我走神的频率会陡然飙升。<br>　　黑板上密密麻麻的公式、老师絮絮叨叨的讲课声全都成了模糊的背景噪音。我的目光、我的心绪、我的注意力，不由自主地系在身侧熟睡的少年身上。我不敢看得太久，怕心跳声太响吵醒他，却又舍不得移开目光，贪婪地收藏着这份只属于我的、独一无二的风景。<br>　　自习课最是难熬，也最是私心泛滥。教室里安安静静，只有笔尖划过纸张的沙沙声。我不敢明目张胆地看他，就假装低头写题，目光透过作业本的缝隙，落在他的手上。<br>　　临渊的手很好看，骨节分明，指尖干净修长，握笔的姿势规整又好看。就是这双手，总能轻松解开所有人头疼的压轴题，总能写下工整漂亮的板书，清冷又强大。那日巷子里夹烟的模样反复在脑海盘旋，一想到那双手握着烟，心口又轻轻揪紧。<br>　　有天午休快结束，课代表挨桌催收课堂作业，临渊用的刚拆开一本崭新的空白作业本，随手丢给我。我看着空白页面，轻轻戳了戳他胳膊："写名字。"<br>　　临渊眼皮耷拉着，脑袋一点一点往桌沿靠，随手把崭新本子往我手边一推，嗓音黏糊糊裹着睡意："你帮我写了吧，我睡会儿。"<br>　　没等我应声，他直接蜷起胳膊枕在桌面，呼吸转瞬就轻缓下来。<br>　　我望着他熟睡的侧脸无奈失笑，指尖捻起黑笔，翻开作业本扉页，认认真真一笔一画落下"临渊"两个字。字迹是我惯常的清隽模样，比写自己名字时还要用心几分，写完和我的作业一并送到讲台。<br>　　往后好长一段日子，这本作业本一直摆在临渊桌角。每次我无意间瞥见封面上我亲手写下的名字，心脏总会不受控制地轻轻颤一下，明明只是简简单单两个字，却藏着只有我自己才懂的、细碎滚烫的心动。<br>　　我会悄悄记住他所有的习惯。<br>　　他喜欢甜食，尤其热衷冰可乐；他做题喜欢从后往前检查；他惯常熬夜，白天经常打瞌睡；他怕热，夏天总会把窗户开到最大，偏爱晚风穿堂的凉意；他讨厌吵闹，班上打闹的时候会蹙着眉塞上耳机。<br>　　我还发现胃不好，三餐不规律经常胃疼，总是不说。自从撞见他抽烟，我又多了一桩放不下的心事，总暗自担心烟酒一同耗损他本就虚弱的身体。<br>　　班里偶尔会有女生偷偷给临渊递情书、塞零食，无一例外，全都被他礼貌拒绝。零食会原样退回，情书看都不会拆开，眼神平静无波，没有丝毫波澜，冷淡得近乎绝情。<br>　　每次看到这一幕，周围同学都在感慨临渊太过清冷无情，只有我坐在一旁，心口又酸又涩，夹杂着一丝卑劣的庆幸。<br>　　庆幸他对所有人都一样疏离，庆幸没有人能真正看透他心底积压的烦闷，庆幸我还能留在他身边，做他最亲近的同桌。<br>　　至少现在，我是离他最近的人。<br>　　哪怕只是同桌，只是普通同学，只是他漫长人生里，微不足道的一个过客。<br>　　有一次月考，我数学没考好，最后一道大题空着大片空白，整张试卷刺眼又难堪。晚自习的时候，我盯着试卷上的红叉，越看越烦躁，低落的情绪压得人喘不过气。<br>　　我以为身边的少年依旧会置若罔闻，自顾自刷题。毕竟他从来不会在意旁人的情绪。<br>　　可没过多久，一只白皙干净的手，轻轻推过来一张答题卡。<br>　　我猛地抬头，撞进临渊漆黑清冷的眼眸里。他的眼神依旧淡淡的，没有太多情绪，声音轻得像晚风，落在我耳边："可以看看我的解题思路，这道题不算太难，你应该能懂"<br>　　那答题卡上，字迹工整清晰，步骤罗列得清清楚楚，繁琐的解题过程，被他梳理得简单通透。<br>　　那一刻，教室的晚风从窗口吹进来，撩动他额前的碎发，带着淡淡的香，隐约掺着一丝若有若无的烟草余味，我的感动里掺着一点说不清的心乱如麻。<br>　　那一整晚，我根本没看进去解题思路，只是小心翼翼地把那张答题卡看了两遍，得出一个结论...这个人字写得很好看。<br>　　评讲试卷的时候把答题卡还回去，那一点怅然若失是我盛大又卑微的喜欢。<br>　　我的暗恋是一场无人知晓的独角戏。<br>　　舞台只有一张课桌的距离，观众只有我自己。主角是永远无动于衷的临渊，配角是偷偷仰望他的我。我不敢告白，不敢表露心意。我们之间的差距太明显了，他是985预备生，前途坦荡，而我将将够得上一本，走不进他的未来。<br>　　我配不上他，于是不敢赌。所以我只能藏着，憋着，忍着。<br>　　把汹涌滚烫的爱意，连同那份挥之不去的揪心，全部压在心底，化作无数个偷偷凝望的瞬间，化作无数次小心翼翼的迁就，化作无数个为他心动又失落、暗自担忧的日夜。<br>　　春去秋来，三年倏忽而过，转眼就到了毕业离校的这天。<br>　　喧闹的教室里挤满了拍照留念、互写赠言的同学，人声鼎沸，阳光滚烫，宣告着我们轰轰烈烈又青涩内敛的青春落幕。<br>　　我和临渊并肩坐了整整三年，到最后，也只剩一句体面的告别。<br>　　我压下心底翻涌的所有不舍，压下藏了三年的喜欢与牵挂，对着他浅浅笑着，语气是最真诚、最普通的老友祝福。<br>　　我说："以后到了新的学校，希望你也能交到好朋友。记得要好好吃饭，别总凑合，不然又会胃疼。"<br>　　话音落下的瞬间，我看见临渊笑了。<br>　　那不是他平日里礼貌疏离、浅淡无痕的敷衍笑意，是一种实在没招了、被我的叮嘱磨得软下来的，近乎温柔的笑。<br>　　冰山消融，霜雪尽散，清冽的少年眉眼骤然柔和下来，温柔得让我心头一震。<br>　　他看着我，声音依旧清冷，却仿佛带着几分缱绻暖意，字字清晰："承蒙厚爱了，也助你前程似锦。"<br>　　我站在原地，久久没能回神。<br>　　心跳乱了节奏，心底一片茫然。<br>　　我始终猜不透他。<br>　　猜不透他这句厚爱，是洞悉了我三年隐秘的暗恋，温柔不点破，还是只是少年得体客套的花腔祝福。<br>　　猜不透他眼底转瞬即逝的温柔，是对我也暗藏几分不自知的心动，还是自始至终，心似一潭死水，从未为我掀起过半分波澜。<br>　　三年暗恋，藏在自习课写名字的悸动里，掺着撞见他独处抽烟时淡淡的心疼，终于在盛夏告别。<br>　　晚风依旧温柔，可我藏了整个青春的心事，终究还是留在了十七岁的课桌旁，留在那本写满我私心的作业本上，留在那条飘着烟味的梧桐小巷里，无人应答，无人揭晓</p>',
'tongzhuo-de-ni', '2026-07-02T23:22:02Z'
FROM users WHERE role = 'admin' LIMIT 1;

