-- 3. 恋哥不是我的错 #2 (2026-06-29)
-- ============================================================
INSERT INTO articles (user_id, title, summary, content, slug, created_at)
SELECT id, '恋哥不是我的错 #2', '对于池峮，边叙仍旧守着十九岁新人打野的那份幼稚可笑的被动和封闭，像是抓着少年时代最后一点儿漫无边际的任性的尾巴',
'<p>　　前一晚集体熬了个大夜过后，首发连教练六人集体没能逃脱床的魔爪。整个早晨…连半个下午基地都沉浸在连糕糕走路都听得见的寂静中。<br>　　边叙从基地外吃过晚饭回来，顺手将一杯明显不是外卖包装的奶茶放在符尧桌上。为此他方才途径一楼餐厅时还不得不承认是为云际带的来面对秦川问询的目光。<br>　　托全基地自上至下共用同一个楼梯的福，与之同时可以清楚地听见符尧被吃不完巨额外卖的秦川一个电话叫下楼吃晚饭的声音，其一惊一乍之程度基地内绝无第二人可及。<br>　　"雨慕慕我来了——"<br>　　正滞留于符尧直播机位侧的边叙怔愣一瞬，随即会心一笑，眉目间是自己都不曾意识到的前所未有的温柔。刹那神情却被训练室角落一人尽数捕捉。</p><p>　　昨日自己不知怎地，平白无故非要把池峮哥…把池教喊下来复盘不说，还无辜连累符尧被两个辅助挨个挑刺，若说心中无愧，于边叙而言自是不可能。<br>　　可赔礼道歉这种小事，放到池峮的身上，却令一向善于交际的边叙格外为难。<br>　　毕竟，就连"善于交际"这个印象出现在边叙身上，也已经是池峮离开YHG之后的事了。而对于池峮，边叙仍旧守着十九岁新人打野的那份幼稚可笑的被动和封闭，像是抓着少年时代最后一点儿漫无边际的任性的尾巴。<br>　　就像，时至今日，他依旧几乎不了解池峮的半点习惯与喜恶，YHG体贴照顾的队长的关心名单上，也从来不会有池峮这么一个名字。<br>　　他不了解他喜欢玩什么英雄，只知道他的桑启很强，也不了解他一贯的作息习惯，却记得当年他拉着YHG1.0的所有人天天复盘到半夜，不结束不许睡觉。<br>　　池峮在边叙心中永远是那个19岁小打野眼中无所不能的队长，永远坚定，正确，可以信赖的存在。</p><p>　　和过分为难的另一边相比，真正的19岁之人，小射手符尧的心思不难懂，甚至可以说是过分好懂。边叙只消随口提到自己今天有外出商务不在基地的事实，便能轻松地从小射手口中收获答案。<br>　　"蔚队又有商务嘛…有钱了该请大伙儿喝奶茶咯。<br>　　唉，某奶茶店上架了新品，我们这怎么就不在配送距离呢，好好奇是什么味道…可恶。"<br>　　刚跑完商务的边叙在回程的出租车上顺手下单奶茶，嘱咐司机稍微绕些路到奶茶店处停一下，嘴角是自己都不曾察觉的笑意。</p><p>　　"你要是怕吃不完可以喊云际帮你分担一点，他肯定乐意。不过嘛…"祁岳话锋一转，<br>　　"不过什么？"秦川随口接茬。<br>　　"不过你得先把这懒虫喊醒…<br>　　真不知道这家伙怎么这么能睡，池教不是已经制裁他半夜玩手机了吗，啧。"<br>　　秦川与祁岳的脸上一时出现了同款的服气表情。<br>　　"欸？说起来，蔚队吃过了吗？我外卖点多了，这边都是完全没动过的。"<br>　　路过被喊住的边叙脚步一顿，暗自想道这种烦恼也就只有秦川会有吧，面上却显几分歉意，简单解释过自己已经吃过晚饭便转身下楼。<br>　　云际还没下楼…倒是刚好趁这时候可以把奶茶放他桌上。边叙仿佛已经预见符尧发现时的惊喜模样。由于离训练时间还早，训练室里除却景程外并无他人。<br>　　听见脚步声的上单适时探出头望向来者，见是边叙又肉眼可见有点紧张地结巴着问好。<br>　　"蔚，蔚队。"<br>　　边叙于是提着奶茶对人温和笑笑，本着队长的身份顺口关心一句饭点便已经在训练室的对方。<br>　　"嗯。怎么就你一个人在这，吃过饭了吧。"<br>　　本以为话题会就此结束，不承想景程却只是轻轻摇了摇头，声音更小了。<br>　　"没有…"<br>　　边叙眼中划过丝惊诧，又很快恢复到温和模样。<br>　　"刚才雨慕点了外卖，有多的，饿的话可以先上去吃点再来。"<br>　　可景程只是把头埋得更低，自手机和电脑的缝隙里闷闷挤出句好便再没了下文。<br>　　直到一颗水果糖被轻轻放在桌上，边叙令人安心的声音自头顶响起。<br>　　"那…吃颗糖吧，不然容易低血糖的。"</p><p>　　符尧看到奶茶的第一时间有些呆滞，就这般站在自己桌边提着刚拿到手的外卖奶茶与自己心心念念的新品面面相觑，不过也迅速反应过来这是队长记住了自己随口念叨的话特地为自己带的，偶像脑的小射手一时脑子里只剩下一个念头：绝对不要让队长觉得自己的好心多余。<br>　　于是他自然而然地略过自己的位置三两步走到景程身侧，将手中奶茶搁在人面前，不忘带上平时面对景程时一贯的嘻嘻哈哈的态度，<br>　　"小尘鲸～喏，奶茶，给你点的。我知道你没吃饭，不要拒绝我呀。"<br>　　与此同时仗着二人座位背对边叙疯狂对人眨眼示意：好尘鲸，同为队长粉丝，你一定也不想看这样一个人因为好意显得尴尬吧。拜托了配合我一下！<br>　　"啊，好…"<br>　　景程从善如流地将奶茶往自己面前推了推示意收下对方好意，符尧于是有点得意地笑起来，双眸满意地眯起来，露出半边酒窝，像得了糖的小孩子。很可爱。<br>　　他明知道的，景程永远不会拒绝他。</p><p>　　十几分钟内几乎所有选手都陆陆续续下来了，符尧和秦川嘻嘻哈哈地凑到边叙座侧旁敲侧击地问询今晚的训练时间，边叙的应对方式则是一人一颗水果糖，一句"明炀也没说"应付过去。祁岳下来没一会儿又觉着闷上楼去了，只说让训练的时候发信息喊他。谁也没问，不过大多也心知肚明大概是往露台去了。不一会儿凌琅火烈鸟一般风风火火又带几分愤慨几分无奈地来了，便也证实众人的猜想。</p><p>　　凌琅揉着空空的肚子单手带上203的门拐上走廊，正准备去一楼觅食一番，途经露台时却可巧撞见倚在栏杆边的祁岳。<br>　　露台的晚风卷着淡淡的烟火气漫过来，祁岳指间夹了支烟，没怎么抽，只随意抵着身侧，眼底懒懒散散的，是训练之余独有的松弛。凌琅见状顺势吐槽出声，二人就这般就着傍晚的闷热拌起闲嘴来。<br>　　"哇，堂堂YHG首发辅助竟然躲在这摸鱼抽烟，池教要是看见肯定又得罚你一个国标。"<br>　　祁岳抬眼瞥他，语气淡得带着点怼人意味："总比某些人天天想着摸鱼干饭，训练没开始就惦记夜宵强。"<br>　　"人家那是合理补充体能！"凌琅一副理直气壮"再说了，喂喂，有些人搁这吹风摆烂还好意思说我？"<br>　　祁岳轻嗤一声捻灭烟，嘴角上升两个像素点，语气中带了丝不常见于此人的意味。<br>　　"当然好意思啊。有人三天两头用室友的钱''补充体能''都没不好意思呢，我为什么不好意思？"<br>　　凌琅并未听出对方话里的挪揄，只贫瘠的语言能力使得他一时有些说不出话，肚子适时地响起提醒着此行的目的，祁岳轻笑一声，轻声提醒人快去找点吃的吧，那人倒也没再还嘴，应着转身下楼去，祁岳目送人背影远了，便也回201休息去。<br>　　露台只剩晚风徐徐。</p><p>　　还未开始训练的训练室里氛围松散，遍寻食物未果的凌琅怨气十足地抱怨着祁岳的毒舌与众人的无情，都不给自己留一口晚饭，秦川有点好笑地附和着左耳进右耳出，顺带嘲笑自己贪睡的室友明明再早起十分钟便能蹭到方才点多了的外卖，留充满怨念的"人家"声在训练室回荡<br>　　符尧半躺在电竞椅上，有一搭没一搭地刷着洋柿子小说的废柴逆袭修仙文，时而爆发出熊二一般的笑声，被秦大少爷无情嘲笑后又显出幅可怜巴巴的神色，凑到小同桌景程处求安慰，景程于是不得不从巅峰赛中抬起头，小心翼翼地偷瞄一眼罪魁祸首秦川，而后略显笨拙地安慰着演技浮夸的好友，直至符尧的嘴角浮现一丝得意的笑，景程便也松下来，闷闷地跟着笑。<br>　　"小尘鲸，你是在笑吗？"<br>　　"没，没有…"</p>',
'liange-bu-shi-wo-de-cuo-2', '2026-06-29T15:08:43Z'
FROM users WHERE role = 'admin' LIMIT 1;

