-- 6. YHG战队校园架空 #1 (2026-06-28)
-- ============================================================
INSERT INTO articles (user_id, title, summary, content, slug, created_at)
SELECT id, 'YHG战队校园架空 #1', 'YHG一群人翻墙逃课去网吧给景程庆生，却被班主任池峮抓包。',
'<p>　　"先把书包扔过来！"<br>　　翻墙逃课这事秦川没少干，很利落地翻到了学校外边，招呼里面几个人罢书包扔过来。<br>　　"神人学校，考完试了还把我们扣下来晚自习。"凌琅第二个翻墙，忍不住吐槽。<br>　　"秦川，翻墙这事没少干啊。"祁岳笑了笑。<br>　　"那是，这么鸟不拉屎的地方还想困住本小姐？"<br>　　"好了好了，动作快一些，待会有人来了。"边叙有些无奈，边望风边让他们小声点，等大家都翻出去后等大家都翻出去后，才跟着翻墙。</p><p>　　"好刺激，这还是我第一次逃课——小鲸鱼，你今天终于成年了，我们终于可以去网吧打排位了！"<br>　　景程依旧有些忐忑，闻言不好意思地低头微笑。<br>　　今天是景程18岁生日，大家决定带他去网吧庆祝，大玩特玩！<br>　　几人来到附近的网吧，开了几台机子，边叙提前订了一个蛋糕，还点了一些零食和饮料，拿出随身携带的消毒湿巾把所有设备仔仔细细擦了一遍。<br>　　他拿起一罐百事可乐，擦了擦罐口，打开拉环递给祁岳。<br>　　"班长——你偏心，我也要你给我开可乐。"符尧探头眨巴眼睛，边叙笑着揉了把符尧的头发，给他也开了一罐。<br>　　给蛋糕点上蜡烛，给景程戴上黄卡纸生日帽，大家快快乐乐地唱生日歌。<br>　　"小鲸鱼，快闭上眼睛许个愿！"符尧道。<br>　　景程闭上眼睛，双手合十静静许愿，然后睁眼轻轻吹灭了蜡烛,"谢谢你们……"<br>　　符尧揽住了他的肩："不要小看我们的羁绊啊！"<br>　　祁岳没忍住笑了笑："尧尧公主的中二期还没过呢？"<br>　　"这个奶油也太差劲了，便宜货，谁订的蛋糕啊。"秦大小姐很是嫌弃。<br>　　"我订的，囊中羞涩，只能买普通款的蛋糕啦，不过是定制的价格也不便宜呢，你看，还有蓝色小鲸鱼的图案……"<br>　　"唉，穷鬼，早知道让本大小姐出钱了。"</p><p>　　几人上了号，痛痛快快打了几把排位，不知是不是沾了小寿星的光几人的胜率特别高。</p><p>　　结束完这一局，边叙发现有人给他发微信，一看，是池峮，他们的生物老师兼班主任。</p><p>　　池峮：班长<br>　　池峮：他们几个，你带出去的吧。<br>　　池峮：游戏好玩吗？^ ^</p><p>　　边叙感到后背凉飕飕的，大家注意到了，纷围过来瞧。</p><p>　　边叙：老师，符尧他身体不舒服，我没来得及请假，所以就……</p><p>　　过了十几秒，对面发来一张游戏界面截图，显示着一个名为"第一我不叫蔚"的好友正上线。</p><p>　　"啊！班长，他怎么有你的好友！"符尧瞪大了眼睛。<br>　　"我忘记了……"边叙头疼扶额。</p><p>　　边叙给池峮发了几张滑跪道歉的表情包。<br>　　边叙：不过老师……今晚是你看晚自习吧，怎么会知道我上线了？<br>　　池峮：嘘。</p>',
'xiao-yuan-jia-kong-1', '2026-06-28T11:02:20Z'
FROM users WHERE role = 'admin' LIMIT 1;
